    /// Seed a policy binding so the N1 handlers have a session to act on.
    fn seed_binding(sm_context_ref: &str, psi: u8) {
        smf_context_init(64, 256, 512);
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                bindings.insert(
                    sm_context_ref.to_string(),
                    context::PolicyBinding {
                        sm_policy_id: None,
                        supi: "imsi-001010000000001".to_string(),
                        psi,
                        pti: 2,
                        pdu_session_type: policy::pdu_session_type::IPV4,
                        ssc_mode: 1,
                        ue_ip: [10, 45, 0, 2],
                        dnn: "internet".to_string(),
                        qfi: 1,
                        five_qi: 9,
                        arp_priority_level: 8,
                        ambr_ul_bps: 100_000_000,
                        ambr_dl_bps: 100_000_000,
                        // No AMF callback URI: nothing to notify, and no
                        // N1N2MessageTransfer is attempted.
                        sm_context_status_uri: None,
                        fsm: gsm_sm::GsmFsm::new(0),
                        // #114: no EASDF DNS context by default, so the release
                        // path has nothing to delete.
                        easdf_dns_context_id: None,
                        mapped_eps_bearer_id: None,
                        easdf_reported_eas: Vec::new(),
                        sst: 1,
                        sd: Some("010203".to_string()),
                        // #293: no SDM subscription by default, so the release path
                        // has nothing to unsubscribe.
                        sdm_subscription_id: None,
                        nsac_admitted: false,
                        nsac_nf_id: None,
                    },
                );
            }
        }
    }

    /// #114: the EASDF DNS-message report sink exists and attributes the report
    /// to the session that owns the DNS context.
    ///
    /// The SMF advertises this URI as the context's `notificationUri`, so a 404
    /// here would mean every report the EASDF sends is dropped — the emit-side-
    /// without-a-sink defect. Asserts the route answers 204 AND that the reported
    /// EAS address landed on the right binding: a 204 alone would pass against a
    /// handler that parsed nothing.
    #[tokio::test]
    async fn easdf_dns_report_is_attributed_to_its_session() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        seed_binding("easdf-report-ref", 7);
        // Give that session a DNS context id to be matched against.
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut("easdf-report-ref") {
                    b.easdf_dns_context_id = Some("ctx-report-1".to_string());
                }
            }
        }

        let req = SbiRequest::post("/nsmf-pdusession/v1/easdf-dns-reports").with_body(
            serde_json::json!({
                "dnsContextId": "ctx-report-1",
                "fqdn": "vr.edge.example.com",
                "action": "RESOLVE",
                "easIpAddresses": ["10.80.0.8"]
            })
            .to_string(),
            "application/json",
        );
        let resp = smf_sbi_request_handler(req).await;
        assert_ne!(resp.status, 404, "the advertised callback must be routed");
        assert_eq!(resp.status, 204);

        let recorded = smf_self()
            .read()
            .ok()
            .and_then(|ctx| {
                ctx.policy_bindings.read().ok().and_then(|b| {
                    b.get("easdf-report-ref")
                        .map(|b| b.easdf_reported_eas.clone())
                })
            })
            .unwrap_or_default();
        assert_eq!(
            recorded,
            vec!["10.80.0.8".to_string()],
            "the reported EAS address must be recorded against the owning session"
        );

        // A report for an unknown context is still 204 (a notification the SMF
        // cannot attribute is not the EASDF's fault to retry) but records nothing.
        let req = SbiRequest::post("/nsmf-pdusession/v1/easdf-dns-reports").with_body(
            serde_json::json!({"dnsContextId": "ctx-nobody", "fqdn": "x", "easIpAddresses": ["1.2.3.4"]})
                .to_string(),
            "application/json",
        );
        assert_eq!(smf_sbi_request_handler(req).await.status, 204);
        let still = smf_self()
            .read()
            .ok()
            .and_then(|ctx| {
                ctx.policy_bindings.read().ok().and_then(|b| {
                    b.get("easdf-report-ref")
                        .map(|b| b.easdf_reported_eas.clone())
                })
            })
            .unwrap_or_default();
        assert_eq!(
            still,
            vec!["10.80.0.8".to_string()],
            "an unattributable report must not overwrite another session's data"
        );

        // A malformed body is refused rather than silently ignored.
        let req = SbiRequest::post("/nsmf-pdusession/v1/easdf-dns-reports")
            .with_body("not json".to_string(), "application/json");
        assert_eq!(smf_sbi_request_handler(req).await.status, 400);
    }

    /// #114: a session that FAILS to establish creates no EASDF DNS context.
    ///
    /// This is the property the call site's placement buys, and the reason it sits
    /// after the PFCP leg rather than before it: a context created for a session
    /// that then fails is an orphan on the EASDF that nothing will ever delete,
    /// because the release path never runs for a session that never existed.
    ///
    /// #289 converted this test: the harness now HAS a UPF stand-in, so the
    /// failure has to be arranged deliberately rather than being the only thing
    /// this harness could produce. The N4 leg fails here because the association
    /// is down, which is the real failure mode (TS 29.244 §6.2.6.2) and the one
    /// `pfcp_session_establish` checks first. The success half — the create call
    /// site actually firing — is
    /// `an_established_session_creates_its_easdf_dns_context` below; until it
    /// existed, removing the `easdf::create_dns_context` call left the whole suite
    /// green (#276).
    #[tokio::test]
    async fn a_failed_establishment_creates_no_easdf_dns_context() {
        // Lock order (see `context::PROCESS_STATE_TEST_LOCK`): ambient state first,
        // N4 second — `stand_in` takes the N4 lock on this test's behalf.
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _upf = pfcp_path::stand_in::unassociated_upf().await;
        let (nrf, easdf_srv, seen) = easdf::tests::spawn_nrf_and_easdf().await;
        smf_context_init(64, 256, 512);
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();

        let body = serde_json::json!({
            "pduSessionId": 5,
            "supi": "imsi-001010000000001",
            "sNssai": { "sst": 1, "sd": "010203" },
            "dnn": "internet",
            "anType": "3GPP_ACCESS",
            "ratType": "NR",
            "n1SmMsg": { "contentId": "n1SmMsg" },
        });
        let n1_msg = n1(
            5,
            1,
            gsm_build::message_type::PDU_SESSION_ESTABLISHMENT_REQUEST,
            &[0x91, 0x00],
        );
        let request = SbiRequest::post("/nsmf-pdusession/v1/sm-contexts")
            .with_body(body.to_string(), "application/json")
            .with_part(nextgcore_sbi::message::SbiPart::with_content(
                "n1SmMsg",
                "application/vnd.3gpp.5gnas",
                n1_msg.into(),
            ));
        let resp = handle_sm_context_create(&request).await;

        // The stand-in UPF is present but NOT associated, so establishment fails
        // at the N4 leg exactly as it does against an unreachable UPF.
        assert_eq!(
            resp.status, 504,
            "an un-associated UPF must fail the N4 leg (TS 29.244 §6.2.6.2)"
        );
        let requests = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        assert!(
            requests.is_empty(),
            "a session that never established must leave no DNS context behind, got {requests:?}"
        );

        easdf::set_for_test(None);
        easdf_srv.stop().await.expect("stop");
        nrf.stop().await.expect("stop");
    }

    /// #289 acceptance: a create that REACHES the success path creates the
    /// session's EASDF DNS context, asserted from `handle_sm_context_create`
    /// rather than by calling `easdf::create_dns_context` directly.
    ///
    /// This is the guard #276 could not write. `create_dns_context` had no
    /// production caller for a month — PR #277 wrote `let easdf_dns_context_id =
    /// None;` under a comment describing the awaited call — and the module's own
    /// over-the-wire test said nothing about it, because a helper's test cannot
    /// see whether a handler calls it. Removing the call from the handler now
    /// fails HERE.
    ///
    /// The recorded `(method, path, body)` list is the assertion, and the UE
    /// address in the body is part of it: the EASDF cannot correlate a UDP query
    /// with a session without it (#276), so a create that omitted it would be a
    /// context that can never match a query.
    #[tokio::test]
    async fn an_established_session_creates_its_easdf_dns_context() {
        // Lock order (see `context::PROCESS_STATE_TEST_LOCK`): ambient state first,
        // N4 second — `stand_in` takes the N4 lock on this test's behalf.
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let upf = pfcp_path::stand_in::associated_upf().await;
        let (nrf, easdf_srv, seen) = easdf::tests::spawn_nrf_and_easdf().await;
        smf_context_init(64, 256, 512);
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();

        let resp = handle_sm_context_create(&create_request(
            "imsi-001010000000289",
            6,
            &n1(
                6,
                1,
                gsm_build::message_type::PDU_SESSION_ESTABLISHMENT_REQUEST,
                &[0x91, 0x00],
            ),
        ))
        .await;
        assert_eq!(
            resp.status, 201,
            "the stand-in UPF answers Session Establishment, so the create must succeed"
        );
        assert!(
            upf.seen()
                .contains(&pfcp_path::pfcp_message_type::SESSION_ESTABLISHMENT_REQUEST),
            "the 201 must have been earned on the N4 wire, not short-circuited"
        );

        let requests = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        let create = requests
            .iter()
            .find(|(m, p, _)| m == "POST" && p.contains("/neasdf-dnscontext/v1/dns-contexts"))
            .unwrap_or_else(|| {
                panic!("the create handler must POST a DNS context, got {requests:?}")
            });
        assert!(
            create.2.contains("imsi-001010000000289"),
            "the DNS context must name the subscriber it belongs to, got {}",
            create.2
        );

        easdf::set_for_test(None);
        easdf_srv.stop().await.expect("stop");
        nrf.stop().await.expect("stop");
    }

    /// #114: releasing a session whose binding carries an EASDF DNS context id
    /// issues the matching DELETE **from the release handler**.
    ///
    /// Added after a revert exposed the hole: with the delete call removed from
    /// `handle_sm_context_release`, the whole suite still passed, because the
    /// easdf module's own test drives `delete_dns_context` directly and says
    /// nothing about whether any handler calls it — "the helper is tested and the
    /// wiring is not", for the third time in this session.
    #[tokio::test]
    async fn releasing_a_session_deletes_its_easdf_dns_context() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let (nrf, easdf_srv, seen) = easdf::tests::spawn_nrf_and_easdf().await;

        seed_binding("easdf-release-ref", 9);
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut("easdf-release-ref") {
                    b.easdf_dns_context_id = Some("ctx-abc".to_string());
                }
            }
        }
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();

        let _ = handle_sm_context_release("easdf-release-ref", None).await;

        let requests = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        assert!(
            requests
                .iter()
                .any(|(m, p, _)| m == "DELETE" && p == "/neasdf-dnscontext/v1/dns-contexts/ctx-abc"),
            "the release handler must delete the session's DNS context, got {requests:?}"
        );

        // A session with NO context id must not cause a delete: nothing to delete,
        // and dialling the EASDF anyway would be a request per released session in
        // every deployment that does not use edge DNS.
        seed_binding("easdf-release-none", 10);
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();
        let _ = handle_sm_context_release("easdf-release-none", None).await;
        assert!(
            seen.lock().unwrap_or_else(|e| e.into_inner()).is_empty(),
            "a session without a DNS context must not dial the EASDF"
        );

        easdf::set_for_test(None);
        easdf_srv.stop().await.expect("stop");
        nrf.stop().await.expect("stop");
    }

    /// A loopback UDM that records every request and answers the four operations the
    /// SMF performs: `sm-data` (with whatever body the caller installs),
    /// `sdm-subscriptions` (201 + Location), the UECM registration (201) and both
    /// deletes (204). Returns the recorded `(method, uri, body)` list (#293).
    ///
    /// Points `UDM_SBI_*` at itself, which is how both discovery paths find a UDM in
    /// tests; the caller must hold [`crate::context::PROCESS_STATE_TEST_LOCK`].
    async fn spawn_recording_udm(
        sm_data: serde_json::Value,
    ) -> (
        nextgcore_sbi::server::SbiServer,
        std::sync::Arc<std::sync::Mutex<Vec<(String, String, String)>>>,
    ) {
        use nextgcore_sbi::message::SbiResponse;
        use nextgcore_sbi::server::{SbiServer, SbiServerConfig};

        let seen: std::sync::Arc<std::sync::Mutex<Vec<(String, String, String)>>> =
            std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let (port_listener, port_addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let port = port_addr.port();
        let udm = SbiServer::on_listener(
            SbiServerConfig::new(std::net::SocketAddr::from(([127, 0, 0, 1], port))),
            port_listener,
        );
        udm.start(move |req: SbiRequest| {
            let sink = sink.clone();
            let sm_data = sm_data.clone();
            async move {
                sink.lock().unwrap_or_else(|e| e.into_inner()).push((
                    req.header.method.clone(),
                    req.header.uri.clone(),
                    req.http.content.clone().unwrap_or_default(),
                ));
                if req.header.method == "DELETE" {
                    return SbiResponse::with_status(204);
                }
                if req.header.uri.contains("/sdm-subscriptions") {
                    return SbiResponse::with_status(201)
                        .with_header(
                            "Location",
                            format!("{}/sub-293", req.header.uri.trim_end_matches('/')),
                        )
                        .with_json_body(&serde_json::json!({ "subscriptionId": "sub-293" }))
                        .unwrap_or_else(|_| SbiResponse::with_status(201));
                }
                if req.header.uri.contains("/sm-data") {
                    return SbiResponse::with_status(200)
                        .with_json_body(&sm_data)
                        .unwrap_or_else(|_| SbiResponse::with_status(200));
                }
                SbiResponse::with_status(201)
            }
        })
        .await
        .expect("udm start");

        std::env::set_var("UDM_SBI_ADDR", "127.0.0.1");
        std::env::set_var("UDM_SBI_PORT", port.to_string());
        (udm, seen)
    }

    /// An `sm-data` body with the given session-AMBR and default 5QI for `internet` on
    /// S-NSSAI `{sst:1, sd:010203}` — the slice `create_request` and `seed_binding`
    /// use — behind a DECOY entry for a different slice.
    ///
    /// The decoy is the point (#293): `sm-data` is one entry per S-NSSAI and
    /// `parse_sm_data` falls back to the FIRST entry when none matches, so a re-read
    /// that lost the session's S-NSSAI would apply these decoy values and look like a
    /// successful update. Any test asserting the real values therefore also asserts
    /// that the re-read stayed scoped to the right slice.
    fn sm_data_with(ul: &str, dl: &str, five_qi: u8) -> serde_json::Value {
        serde_json::json!([
            {
                "singleNssai": { "sst": 2 },
                "dnnConfigurations": {
                    "internet": {
                        "sessionAmbr": { "uplink": "1 Mbps", "downlink": "2 Mbps" },
                        "5gQosProfile": { "5qi": 9, "arp": { "priorityLevel": 15 } }
                    }
                }
            },
            {
                "singleNssai": { "sst": 1, "sd": "010203" },
                "dnnConfigurations": {
                    "internet": {
                        "sessionAmbr": { "uplink": ul, "downlink": dl },
                        "5gQosProfile": { "5qi": five_qi, "arp": { "priorityLevel": 8 } }
                    }
                }
            }
        ])
    }

    /// Seed a binding that carries an assigned EBI and an AMF callback root, i.e.
    /// the state a session established with EPS interworking on leaves behind (#291).
    fn seed_binding_with_ebi(sm_context_ref: &str, psi: u8, ebi: u8, amf_uri: &str) {
        seed_binding(sm_context_ref, psi);
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut(sm_context_ref) {
                    b.mapped_eps_bearer_id = Some(ebi);
                    b.sm_context_status_uri = Some(amf_uri.to_string());
                }
            }
        }
    }

    /// A loopback AMF that answers `assign-ebi` with an `AssignedEbiData` echoing
    /// the released list, and records every request it received (#291).
    async fn spawn_recording_amf() -> (
        nextgcore_sbi::server::SbiServer,
        String,
        std::sync::Arc<std::sync::Mutex<Vec<(String, String, String)>>>,
    ) {
        use nextgcore_sbi::message::SbiResponse;
        use nextgcore_sbi::server::{SbiServer, SbiServerConfig};

        let seen: std::sync::Arc<std::sync::Mutex<Vec<(String, String, String)>>> =
            std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let (port_listener, port_addr) = nextgcore_sbi::test_support::bound_listener().into_parts();
        let port = port_addr.port();
        let amf = SbiServer::on_listener(
            SbiServerConfig::new(std::net::SocketAddr::from(([127, 0, 0, 1], port))),
            port_listener,
        );
        amf.start(move |req: SbiRequest| {
            let sink = sink.clone();
            async move {
                let body = req.http.content.clone().unwrap_or_default();
                sink.lock().unwrap_or_else(|e| e.into_inner()).push((
                    req.header.method.clone(),
                    req.header.uri.clone(),
                    body.clone(),
                ));
                if !req.header.uri.ends_with("/assign-ebi") {
                    // The RELEASED status notification lands here too; 204 is what
                    // an AMF answers it with.
                    return SbiResponse::with_status(204);
                }
                let released = serde_json::from_str::<serde_json::Value>(&body)
                    .ok()
                    .and_then(|b| b.get("releasedEbiList").cloned())
                    .unwrap_or_else(|| serde_json::json!([]));
                SbiResponse::with_status(200)
                    .with_json_body(&serde_json::json!({
                        "pduSessionId": 5,
                        "assignedEbiList": [],
                        "releasedEbiList": released,
                    }))
                    .unwrap_or_else(|_| SbiResponse::with_status(200))
            }
        })
        .await
        .expect("amf start");
        (amf, format!("http://127.0.0.1:{port}"), seen)
    }

    /// #291 criterion 1: releasing a session whose binding carries an EBI returns
    /// that EBI to the AMF in a `releasedEbiList`, asserted **over the wire from the
    /// release handler**.
    ///
    /// Driven through `handle_sm_context_release` rather than by calling
    /// `eps_iwk::release_ebi`, because the helper-is-tested-and-the-wiring-is-not
    /// shape has bitten this exact area twice (#276's dead `create_dns_context`, and
    /// #117's IE emitted only from builders with no production caller). What is
    /// asserted is a recorded HTTP request with the identity in it.
    #[tokio::test]
    async fn releasing_a_session_returns_its_ebi_to_the_amf() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        eps_iwk::set_for_test(true);
        let (amf, amf_uri, seen) = spawn_recording_amf().await;

        seed_binding_with_ebi("ebi-release-ref", 5, 7, &amf_uri);
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();

        let resp = handle_sm_context_release("ebi-release-ref", None).await;
        assert_eq!(resp.status, 204, "the release itself must succeed");

        let requests = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        let release = requests
            .iter()
            .find(|(m, p, _)| m == "POST" && p.ends_with("/assign-ebi"))
            .unwrap_or_else(|| {
                panic!("the release handler must return the EBI to the AMF, got {requests:?}")
            });
        assert_eq!(
            release.1, "/namf-comm/v1/ue-contexts/imsi-001010000000001/assign-ebi",
            "addressed to the UE's own ue-context (TS 29.518 §6.1.6.2.5)"
        );
        let body: serde_json::Value =
            serde_json::from_str(&release.2).expect("the request body is JSON");
        assert_eq!(
            body["releasedEbiList"],
            serde_json::json!([7]),
            "the identity on the binding is the one handed back, got {body}"
        );
        assert_eq!(
            body["pduSessionId"],
            serde_json::json!(5),
            "pduSessionId is AssignEbiData's only required member"
        );
        assert!(
            body.get("arpList").is_none(),
            "a release must not ask for a new EBI in the same breath, got {body}"
        );

        // A session with NO EBI must not dial the AMF's assign-ebi at all: an SMF
        // that did would send one request per released session in every deployment
        // that does not use interworking.
        seed_binding("ebi-release-none", 6);
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut("ebi-release-none") {
                    b.sm_context_status_uri = Some(amf_uri.clone());
                }
            }
        }
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();
        let _ = handle_sm_context_release("ebi-release-none", None).await;
        assert!(
            !seen
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .iter()
                .any(|(_, p, _)| p.ends_with("/assign-ebi")),
            "a session that never had an EBI must not dial assign-ebi"
        );

        eps_iwk::set_for_test(false);
        amf.stop().await.expect("stop");
    }

    /// #291 criterion 5: with interworking disabled the release path sends nothing,
    /// even for a binding that carries an EBI from an earlier enabled run.
    #[tokio::test]
    async fn a_disabled_interworking_leg_releases_no_ebi() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        eps_iwk::set_for_test(false);
        let (amf, amf_uri, seen) = spawn_recording_amf().await;

        seed_binding_with_ebi("ebi-release-off", 5, 8, &amf_uri);
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();

        assert_eq!(
            handle_sm_context_release("ebi-release-off", None)
                .await
                .status,
            204
        );
        assert!(
            !seen
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .iter()
                .any(|(_, p, _)| p.ends_with("/assign-ebi")),
            "a disabled leg must not dial the AMF"
        );

        amf.stop().await.expect("stop");
    }

    /// #415 criterion 7: with the interworking leg OFF, a create carrying a container
    /// behaves exactly as one without it.
    ///
    /// Standalone 5GC and standalone EPC must be unchanged,
    /// and the way to show that is that the response carries none of step 7's members.
    #[tokio::test]
    async fn a_container_on_a_create_changes_nothing_when_the_leg_is_off() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let _upf = pfcp_path::stand_in::associated_upf().await;
        eps_iwk::set_for_test(false);
        smf_context_init(64, 256, 512);

        let supi = "imsi-001010000000416";
        let psi = 13u8;
        let mut request = create_request(
            supi,
            psi,
            &n1(
                psi,
                1,
                gsm_build::message_type::PDU_SESSION_ESTABLISHMENT_REQUEST,
                &[0x91, 0x00],
            ),
        );
        {
            use base64::Engine as _;
            let mut body: serde_json::Value =
                serde_json::from_str(request.http.content.as_deref().expect("body")).expect("json");
            // #78's positional layout this time, so the off-path is exercised against the
            // container this tree's own SMF actually produces.
            let container = {
                let mut buf = vec![APN_OFF.len() as u8];
                buf.extend_from_slice(APN_OFF.as_bytes());
                buf.push(1);
                buf.extend_from_slice(&[10, 45, 4, 16]);
                buf.push(8);
                buf.push(9);
                buf
            };
            body["ueEpsPdnConnection"] =
                serde_json::json!(base64::engine::general_purpose::STANDARD.encode(&container));
            request.http.content = Some(body.to_string());
        }

        let resp = handle_sm_context_create(&request).await;
        assert_eq!(resp.status, 201, "an ordinary create must still succeed");
        let body: serde_json::Value =
            serde_json::from_str(resp.http.content.as_deref().expect("JSON root")).expect("json");
        // No hoState was sent, so none of step 7's members are owed. Asserted as absence
        // of each member rather than equality on the whole body, which would break every
        // time an unrelated member is added.
        for absent in [
            "hoState",
            "ebiQfiMapping",
            "epsBearerInfo",
            "dataForwardingNotPossible",
        ] {
            assert!(
                body.get(absent).is_none(),
                "a create with no hoState is not a handover preparation, so it must not \
                 carry {absent}; got {body}"
            );
        }
    }

    /// The APN the leg-off test uses, distinct from the preparation test's.
    const APN_OFF: &str = "internet";

    /// #291 criterion 3: a failed release does not fail the session release.
    ///
    /// The session is going away either way, so the SMF cannot make its own
    /// teardown depend on the AMF answering. Port 1 is closed, so the request
    /// fails at connect.
    #[tokio::test]
    async fn a_failed_ebi_release_does_not_fail_the_session_release() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        eps_iwk::set_for_test(true);

        seed_binding_with_ebi("ebi-release-dead", 5, 9, "http://127.0.0.1:1");
        let resp = handle_sm_context_release("ebi-release-dead", None).await;
        assert_eq!(
            resp.status, 204,
            "an unreachable AMF must not turn a session release into a failure"
        );
        // The binding is gone regardless: the release completed locally.
        assert!(
            lookup_policy_binding("ebi-release-dead").is_none(),
            "the release must complete even when the EBI could not be returned"
        );

        eps_iwk::set_for_test(false);
    }

    /// #293 criteria 1 + 4: the create subscribes to SM data, and the release both
    /// deregisters the serving-SMF record and deletes that subscription.
    ///
    /// End to end through the real handlers, which #289's UPF stand-in is what makes
    /// possible: before it, no test could drive a create past its N4 leg, so a
    /// subscribe on the establishment path could only have been asserted by calling
    /// the helper — the shape that let #276's dead `create_dns_context` survive a month.
    ///
    /// Lock order (see `pfcp_path::N4_TEST_LOCK`): switch locks first, N4 last.
    #[tokio::test]
    async fn the_create_subscribes_to_sm_data_and_the_release_deregisters_and_unsubscribes() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let upf = pfcp_path::stand_in::associated_upf().await;
        let (udm_srv, seen) = spawn_recording_udm(sm_data_with("100 Mbps", "500 Mbps", 7)).await;
        udm::set_for_test(true);
        smf_context_init(64, 256, 512);

        let supi = "imsi-001010000000293";
        let psi = 8u8;
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();
        let resp = handle_sm_context_create(&create_request(
            supi,
            psi,
            &n1(
                psi,
                1,
                gsm_build::message_type::PDU_SESSION_ESTABLISHMENT_REQUEST,
                &[0x91, 0x00],
            ),
        ))
        .await;
        assert_eq!(resp.status, 201, "the create must reach the success path");
        let sm_context_ref = serde_json::from_str::<serde_json::Value>(
            resp.http.content.as_deref().expect("JSON root"),
        )
        .expect("json")["smContextRef"]
            .as_str()
            .expect("smContextRef")
            .to_string();
        assert!(
            upf.seen()
                .contains(&pfcp_path::pfcp_message_type::SESSION_ESTABLISHMENT_REQUEST),
            "the 201 must have been earned on the N4 wire"
        );

        let requests = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        let sub = requests
            .iter()
            .find(|(m, u, _)| m == "POST" && u.contains("/sdm-subscriptions"))
            .unwrap_or_else(|| panic!("the create must send Nudm_SDM_Subscribe, got {requests:?}"));
        assert_eq!(
            sub.1,
            format!("/nudm-sdm/v2/{supi}/sdm-subscriptions"),
            "TS 29.503 §5.2.2.3's collection, at v2 like the rest of Nudm_SDM"
        );
        let body: serde_json::Value = serde_json::from_str(&sub.2).expect("json");
        for required in ["nfInstanceId", "callbackReference", "monitoredResourceUris"] {
            assert!(
                body.get(required).is_some(),
                "SdmSubscription.{required} is required, got {body}"
            );
        }
        let callback = body["callbackReference"].as_str().unwrap_or_default();
        assert!(
            callback.ends_with(&format!("/nsmf-callback/v1/sdm-notify/{sm_context_ref}")),
            "the callback must name the route this SMF serves and the session it is \
             for, got {callback}"
        );
        assert!(
            body["monitoredResourceUris"][0]
                .as_str()
                .unwrap_or_default()
                .contains("/sm-data"),
            "the monitored resource is the sm-data document this session depends on, \
             got {body}"
        );
        // The subscription id is recorded on the binding, or the release could not
        // delete it (the orphan case `subscribe_sm_data` warns about).
        assert_eq!(
            lookup_policy_binding(&sm_context_ref).and_then(|b| b.sdm_subscription_id),
            Some("sub-293".to_string()),
            "the id from the Location header must be stored with the binding"
        );

        // ---- release: the UECM record goes, and so does the subscription ----
        seen.lock().unwrap_or_else(|e| e.into_inner()).clear();
        assert_eq!(
            handle_sm_context_release(&sm_context_ref, None)
                .await
                .status,
            204
        );
        let requests = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
        assert!(
            requests.iter().any(|(m, u, _)| m == "DELETE"
                && u == &format!("/nudm-uecm/v1/{supi}/registrations/smf-registrations/{psi}")),
            "the release must remove the serving-SMF record for its own pduSessionId, \
             got {requests:?}"
        );
        assert!(
            requests.iter().any(|(m, u, _)| m == "DELETE"
                && u == &format!("/nudm-sdm/v2/{supi}/sdm-subscriptions/sub-293")),
            "the release must delete the SDM subscription it created, got {requests:?}"
        );

        udm::set_for_test(false);
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
        udm_srv.stop().await.expect("stop");
    }

    /// #293 criterion 3: the notification callback applies a changed session-AMBR and
    /// default 5QI to a LIVE session, read back off the session and the binding.
    ///
    /// Also the PCF-precedence half (criterion 5): the same notification against a
    /// session a PCF authorised changes nothing, because TS 23.503 §6.1.3.2 makes the
    /// PCF the authority and the subscription is one of its inputs.
    #[tokio::test]
    async fn a_sdm_notification_applies_the_changed_ambr_to_a_live_session() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        // The UDM now answers with DIFFERENT values from the ones the session holds.
        let (udm_srv, seen) = spawn_recording_udm(sm_data_with("40 Mbps", "80 Mbps", 6)).await;
        udm::set_for_test(true);
        smf_context_init(64, 256, 512);

        // A real registered session, so the fill-in the handler updates is there to
        // read back.
        let supi = "imsi-001010000000296";
        let sm_context_ref = {
            let ctx = smf_self();
            let context = ctx.read().expect("context");
            let (reference, _id) = register_sm_context(&context, supi, 9).expect("register");
            reference
        };
        seed_binding(&sm_context_ref, 9);
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut(&sm_context_ref) {
                    b.supi = supi.to_string();
                    b.sdm_subscription_id = Some("sub-293".to_string());
                }
            }
        }

        let notify = |reference: &str| {
            SbiRequest::post(format!("/nsmf-callback/v1/sdm-notify/{reference}")).with_body(
                serde_json::json!({
                    "notifyItems": [{
                        "resourceId": format!("/nudm-sdm/v2/{supi}/sm-data"),
                        "changes": [{ "op": "REPLACE", "path": "/sessionAmbr" }],
                    }]
                })
                .to_string(),
                "application/json",
            )
        };

        let resp = smf_sbi_request_handler(notify(&sm_context_ref)).await;
        assert_eq!(
            resp.status, 204,
            "a notification for a live session is a 204"
        );

        // The session and the binding must BOTH carry the new values: the Retrieve and
        // the EPS-interworking encoders read the session, the update and release paths
        // read the binding, and a change applied to one leaves them disagreeing.
        let binding = lookup_policy_binding(&sm_context_ref).expect("binding");
        assert_eq!(
            (binding.ambr_ul_bps, binding.ambr_dl_bps, binding.five_qi),
            (40_000_000, 80_000_000, 6),
            "the changed subscription must reach the binding"
        );
        let sess = smf_self()
            .read()
            .expect("context")
            .sess_find_by_sm_context_ref(&sm_context_ref)
            .expect("session");
        assert_eq!(
            (sess.session_ambr.uplink, sess.session_ambr.downlink),
            (40_000_000, 80_000_000),
            "and the session, which is what Retrieve answers with"
        );
        assert!(
            seen.lock()
                .unwrap_or_else(|e| e.into_inner())
                .iter()
                .any(|(m, u, _)| m == "GET" && u.contains("/sm-data")),
            "the change is RE-READ from the UDM rather than parsed out of the \
             notification -- see handle_sdm_notification"
        );

        // ---- PCF precedence (#293 criterion 5, as #310 left it) ----
        //
        // A PCF-authorised session is STILL not re-derived from the subscription — the
        // PCF is the authority (TS 23.503 §6.1.3.2). What #310 changed is that the
        // change is now REPORTED to the PCF instead of dropped; the SMF applies the
        // PCF's answer, never the subscription. Here the PCF is unreachable (port 1),
        // so there is no answer and the session keeps what the PCF last authorised —
        // the safe state, and explicitly NOT the subscribed value.
        std::env::set_var("PCF_URI", "http://127.0.0.1:1");
        let pcf_ref = {
            let ctx = smf_self();
            let context = ctx.read().expect("context");
            let (reference, _id) = register_sm_context(&context, supi, 10).expect("register");
            reference
        };
        seed_binding(&pcf_ref, 10);
        if let Ok(ctx) = smf_self().read() {
            if let Ok(mut bindings) = ctx.policy_bindings.write() {
                if let Some(b) = bindings.get_mut(&pcf_ref) {
                    b.supi = supi.to_string();
                    b.sm_policy_id = Some("pol-1".to_string());
                }
            }
        }
        let before = lookup_policy_binding(&pcf_ref).expect("binding");
        assert_eq!(smf_sbi_request_handler(notify(&pcf_ref)).await.status, 204);
        let after = lookup_policy_binding(&pcf_ref).expect("binding");
        assert_eq!(
            (after.ambr_ul_bps, after.ambr_dl_bps, after.five_qi),
            (before.ambr_ul_bps, before.ambr_dl_bps, before.five_qi),
            "a PCF-authorised session must not be re-derived from the subscription: \
             TS 23.503 §6.1.3.2 makes the PCF the authority, and the subscription is \
             one of ITS inputs. With the PCF unreachable the session keeps the QoS the \
             PCF last authorised (40/80 Mbps would be the SUBSCRIBED value leaking in)"
        );
        assert_ne!(
            (after.ambr_ul_bps, after.ambr_dl_bps),
            (40_000_000, 80_000_000),
            "and specifically NOT the subscribed value the UDM just reported"
        );
        std::env::remove_var("PCF_URI");

        // A notification for a session this SMF does not hold is a 404, which is what
        // tells the UDM to stop notifying a subscription that outlived its session.
        assert_eq!(
            smf_sbi_request_handler(notify("no-such-ref")).await.status,
            404
        );
        // A malformed body is refused rather than silently accepted.
        assert_eq!(
            smf_sbi_request_handler(
                SbiRequest::post(format!("/nsmf-callback/v1/sdm-notify/{sm_context_ref}"))
                    .with_body("not json".to_string(), "application/json")
            )
            .await
            .status,
            400
        );

        udm::set_for_test(false);
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
        udm_srv.stop().await.expect("stop");
    }

    // ==================================================================
    // #80: N4 usage reporting — the SMF provisions a URR
    // ==================================================================

    /// Split a flat IE stream into `(type, value)` pairs (#80).
    ///
    /// A local TLV walker rather than the builder's own encoder, so a wrong layout
    /// cannot be agreed with by the thing checking it.
    fn flat_ies(buf: &[u8]) -> Vec<(u16, Vec<u8>)> {
        let mut out = Vec::new();
        let mut rest = buf;
        while rest.len() >= 4 {
            let ty = u16::from_be_bytes([rest[0], rest[1]]);
            let len = u16::from_be_bytes([rest[2], rest[3]]) as usize;
            if rest.len() < 4 + len {
                break;
            }
            out.push((ty, rest[4..4 + len].to_vec()));
            rest = &rest[4 + len..];
        }
        out
    }

    /// #797: the Session Establishment Request carries the configured Node ID (the
    /// Service FQDN on k8s) and a CP F-SEID with the routable F-SEID address. Before
    /// #797 both were `SMF_PFCP_ADDR`, so a wildcard bind put 0.0.0.0 in both and the
    /// UPF had no address for this CP function.
    #[tokio::test]
    async fn the_establishment_carries_the_node_id_and_a_routable_f_seid() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let identity = n4_identity::N4Identity {
            node_id: nextgcore_pfcp::types::NodeId::new_fqdn(
                "smf.nextg-system.svc.cluster.local".into(),
            ),
            f_seid_ipv4: [10, 1, 2, 3],
            node_id_explicit: true,
        };
        let upf = pfcp_path::stand_in::associated_upf_as(&identity).await;
        let qos = SessionQos {
            qfi: 9,
            ambr_ul_bps: 100_000_000,
            ambr_dl_bps: 100_000_000,
            xr_flow: None,
        };
        pfcp_session_establish(0x0797, [10, 45, 7, 97], "internet", 1, &qos)
            .await
            .expect("the stand-in UPF must accept the establishment");

        let bodies = upf.establishment_bodies();
        assert_eq!(bodies.len(), 1);
        let ies = flat_ies(&bodies[0]);
        let ie = |ty: u16| -> Vec<u8> {
            ies.iter()
                .find(|(t, _)| *t == ty)
                .map(|(_, v)| v.clone())
                .unwrap_or_else(|| panic!("IE {ty} missing"))
        };
        let mut want_node_id = vec![2u8];
        for label in ["smf", "nextg-system", "svc", "cluster", "local"] {
            want_node_id.push(label.len() as u8);
            want_node_id.extend_from_slice(label.as_bytes());
        }
        assert_eq!(ie(n4_build::pfcp_ie::NODE_ID), want_node_id);
        // F-SEID (§8.2.37): flags (V4 = bit 2), SEID, IPv4.
        let f_seid = ie(n4_build::pfcp_ie::F_SEID);
        assert_eq!(f_seid[0] & 0x02, 0x02, "V4 set");
        assert_eq!(u64::from_be_bytes(f_seid[1..9].try_into().unwrap()), 0x0797);
        assert_eq!(&f_seid[9..13], &[10, 1, 2, 3]);
    }

    /// #80 criterion 1: the LIVE establishment path provisions a Create URR, and both
    /// the UL and DL PDRs carry its URR ID.
    ///
    /// Driven through the real `pfcp_session_establish` against the stand-in UPF and
    /// asserted on the **recorded wire body**, because the whole shape of this defect was
    /// "the builder exists and nothing on the live path calls it": a test against
    /// `build_create_urr` would have passed before #80 and still does.
    ///
    /// The quota is deliberately configured here so the VOLQU/TIMQU triggers are on the
    /// wire too, and deliberately absent in
    /// `an_unconfigured_quota_provisions_measurement_without_enforcement` — the pair is
    /// what shows the gate is the provisioned value rather than a build flag.
    #[tokio::test]
    async fn the_establishment_request_provisions_a_urr_bound_to_both_pdrs() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let upf = pfcp_path::stand_in::associated_upf().await;
        std::env::set_var("SMF_URR_VOLUME_QUOTA", "5000000");
        std::env::set_var("SMF_URR_TIME_QUOTA", "900");
        std::env::set_var("SMF_URR_VOLUME_THRESHOLD", "1000000");
        std::env::set_var("SMF_URR_MEASUREMENT_PERIOD", "30");
        upf.clear_seen();

        let qos = SessionQos {
            qfi: 9,
            ambr_ul_bps: 100_000_000,
            ambr_dl_bps: 100_000_000,
            xr_flow: None,
        };
        pfcp_session_establish(0x0080, [10, 45, 0, 80], "internet", 1, &qos)
            .await
            .expect("the stand-in UPF must accept the establishment");

        let bodies = upf.establishment_bodies();
        assert_eq!(bodies.len(), 1, "exactly one establishment was sent");
        let ies = flat_ies(&bodies[0]);

        // ---- a Create URR is on the wire at all ----
        let urr_ies: Vec<&Vec<u8>> = ies
            .iter()
            .filter(|(t, _)| *t == n4_build::pfcp_ie::CREATE_URR)
            .map(|(_, v)| v)
            .collect();
        assert_eq!(
            urr_ies.len(),
            1,
            "the establishment must provision exactly one Create URR (TS 29.244 \
             §7.5.2.4); before #80 it provisioned none, so the UPF measured nothing"
        );
        let urr = flat_ies(urr_ies[0]);
        let urr_field = |ty: u16| -> Vec<u8> {
            urr.iter()
                .find(|(t, _)| *t == ty)
                .map(|(_, v)| v.clone())
                .unwrap_or_else(|| panic!("IE {ty} missing from the Create URR: {urr:?}"))
        };
        assert_eq!(
            urr_field(n4_build::pfcp_ie::URR_ID),
            SESSION_URR_ID.to_be_bytes()
        );
        // Volume AND duration measurement: a time quota is unmeasurable without duration.
        assert_eq!(urr_field(n4_build::pfcp_ie::MEASUREMENT_METHOD), vec![0x03]);
        let triggers = urr_field(n4_build::pfcp_ie::REPORTING_TRIGGERS);
        assert_eq!(triggers[0] & 0x02, 0x02, "VOLTH");
        assert_eq!(triggers[0] & 0x04, 0x04, "TIMTH");
        assert_eq!(triggers[0] & 0x01, 0x01, "PERIO");
        assert_eq!(
            triggers[1] & 0x01,
            0x01,
            "VOLQU, since a volume quota is set"
        );
        assert_eq!(triggers[1] & 0x02, 0x02, "TIMQU, since a time quota is set");
        // The configured quota, on the wire, as the flags+u64 body §8.2.40 states.
        let mut expect_quota = vec![0x01u8];
        expect_quota.extend_from_slice(&5_000_000u64.to_be_bytes());
        assert_eq!(urr_field(n4_build::pfcp_ie::VOLUME_QUOTA), expect_quota);
        assert_eq!(
            urr_field(n4_build::pfcp_ie::TIME_QUOTA),
            900u32.to_be_bytes()
        );
        assert_eq!(
            urr_field(n4_build::pfcp_ie::MEASUREMENT_PERIOD),
            30u32.to_be_bytes(),
            "PERIO without a Measurement Period is a trigger with no cadence"
        );

        // ---- BOTH PDRs are bound to it ----
        let pdrs: Vec<Vec<(u16, Vec<u8>)>> = ies
            .iter()
            .filter(|(t, _)| *t == n4_build::pfcp_ie::CREATE_PDR)
            .map(|(_, v)| flat_ies(v))
            .collect();
        assert_eq!(pdrs.len(), 2, "one UL and one DL PDR");
        for (i, pdr) in pdrs.iter().enumerate() {
            let bound: Vec<Vec<u8>> = pdr
                .iter()
                .filter(|(t, _)| *t == n4_build::pfcp_ie::URR_ID)
                .map(|(_, v)| v.clone())
                .collect();
            assert_eq!(
                bound,
                vec![SESSION_URR_ID.to_be_bytes().to_vec()],
                "PDR #{i} must reference the session URR; a URR nothing references \
                 measures nothing, and BOTH directions must accumulate against ONE \
                 allowance or a subscriber downloads past a quota they uploaded to. \
                 PDR was {pdr:?}"
            );
        }

        for k in [
            "SMF_URR_VOLUME_QUOTA",
            "SMF_URR_TIME_QUOTA",
            "SMF_URR_VOLUME_THRESHOLD",
            "SMF_URR_MEASUREMENT_PERIOD",
        ] {
            std::env::remove_var(k);
        }
    }

    /// #80 Decision 1: with no quota configured the establishment still provisions
    /// measurement and reporting, and provisions NO quota — so the UPF's forwarding
    /// behaviour is byte-for-byte what it was.
    ///
    /// This is what replaces the off-by-default feature flag #80's "feature-gate advice"
    /// asks for: the gate is the provisioned value, which is what TS 29.244 makes the
    /// gate. Both states are therefore inside `cargo test --workspace`, which a cargo
    /// feature would not be.
    #[tokio::test]
    async fn an_unconfigured_quota_provisions_measurement_without_enforcement() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let upf = pfcp_path::stand_in::associated_upf().await;
        for k in ["SMF_URR_VOLUME_QUOTA", "SMF_URR_TIME_QUOTA"] {
            std::env::remove_var(k);
        }
        upf.clear_seen();

        let qos = SessionQos {
            qfi: 9,
            ambr_ul_bps: 100_000_000,
            ambr_dl_bps: 100_000_000,
            xr_flow: None,
        };
        pfcp_session_establish(0x0081, [10, 45, 0, 81], "internet", 1, &qos)
            .await
            .expect("establish");

        let bodies = upf.establishment_bodies();
        let urr = flat_ies(
            flat_ies(&bodies[0])
                .into_iter()
                .find(|(t, _)| *t == n4_build::pfcp_ie::CREATE_URR)
                .map(|(_, v)| v)
                .expect(
                    "a URR is provisioned even with no quota: measurement is not \
                         enforcement, and without it there is no usage reporting",
                )
                .as_slice(),
        );
        // Measurement and reporting: present.
        assert!(urr
            .iter()
            .any(|(t, _)| *t == n4_build::pfcp_ie::VOLUME_THRESHOLD));
        assert!(urr
            .iter()
            .any(|(t, _)| *t == n4_build::pfcp_ie::MEASUREMENT_PERIOD));
        // Enforcement: absent, values AND triggers.
        assert!(
            !urr.iter()
                .any(|(t, _)| *t == n4_build::pfcp_ie::VOLUME_QUOTA
                    || *t == n4_build::pfcp_ie::TIME_QUOTA),
            "no quota configured must mean no quota IE: the UPF cannot gate traffic it \
             was given no limit for"
        );
        let triggers = urr
            .iter()
            .find(|(t, _)| *t == n4_build::pfcp_ie::REPORTING_TRIGGERS)
            .map(|(_, v)| v.clone())
            .expect("triggers");
        assert_eq!(
            triggers[1] & 0x03,
            0x00,
            "VOLQU/TIMQU must be clear: announcing a quota trigger with no quota names \
             a limit that does not exist"
        );
    }

    /// #80: a zero or unparseable quota is ignored rather than honoured.
    ///
    /// A zero volume quota would gate the subscriber from the first packet. That is far
    /// more likely a misconfiguration than an intent, and TS 29.244 already has a way to
    /// say "no quota" — the IE's absence.
    #[test]
    fn a_zero_or_unparseable_quota_is_ignored() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.blocking_lock();
        std::env::set_var("SMF_URR_VOLUME_QUOTA", "0");
        std::env::set_var("SMF_URR_TIME_QUOTA", "not-a-number");
        let params = session_urr_params();
        assert!(
            params.volume_quota.is_none(),
            "a zero volume quota must be ignored, not gate every packet"
        );
        assert!(
            params.time_quota.is_none(),
            "an unparseable quota is no quota"
        );
        assert_eq!(
            params.reporting_triggers & n4_build::reporting_trigger::VOLQU,
            0,
            "and no quota means no quota trigger"
        );

        // A real value is honoured, so the rejection above is about the value and not
        // about the variable being read at all.
        std::env::set_var("SMF_URR_VOLUME_QUOTA", "12345");
        let params = session_urr_params();
        assert_eq!(params.volume_quota, Some((Some(12345), None, None)));
        assert_ne!(
            params.reporting_triggers & n4_build::reporting_trigger::VOLQU,
            0
        );

        for k in ["SMF_URR_VOLUME_QUOTA", "SMF_URR_TIME_QUOTA"] {
            std::env::remove_var(k);
        }
    }

    /// #853: a release the UE completes (here the #39 reactivation release a UPF
    /// restart sends, then the UE's PDU SESSION RELEASE COMPLETE) tells the UDM as the
    /// AMF-driven release does: the serving-SMF registration is deregistered and the
    /// SDM subscription removed. The UE's address goes back to the pool. Before, every
    /// such release left both at the UDM, and held the address.
    #[tokio::test]
    async fn a_ue_completed_release_deregisters_from_the_udm_and_frees_the_address() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        let (udm_srv, seen) = spawn_recording_udm(serde_json::json!({})).await;
        udm::set_for_test(true);
        let reference = "n853-complete";
        seed_binding(reference, 5);
        let ue_ip = std::net::Ipv4Addr::new(10, 45, 8, 53);
        let reserved = smf_self().read().unwrap().ipv4_pool.reserve(ue_ip);
        if let Ok(ctx) = smf_self().read() {
            if let Some(b) = ctx.policy_bindings.write().unwrap().get_mut(reference) {
                b.sdm_subscription_id = Some("sub-853".to_string());
                b.ue_ip = ue_ip.octets();
            }
        }
        release_for_reactivation(reference, "http://127.0.0.1:1", "imsi-001010000000001", 5).await;

        let complete = n1(
            5,
            0,
            gsm_build::message_type::PDU_SESSION_RELEASE_COMPLETE,
            &[],
        );
        let status = handle_n1_sm_message(reference, &complete).await.status;
        let deletes = || {
            seen.lock()
                .unwrap_or_else(|e| e.into_inner())
                .iter()
                .filter(|(m, _, _)| m == "DELETE")
                .map(|(_, u, _)| u.clone())
                .collect::<Vec<String>>()
        };
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while deletes().len() < 2 && std::time::Instant::now() < deadline {
            tokio::time::sleep(std::time::Duration::from_millis(20)).await;
        }
        let deletes = deletes();
        let freed = smf_self().read().unwrap().ipv4_pool.reserve(ue_ip);
        if freed {
            smf_self().read().unwrap().ipv4_pool.release(ue_ip);
        }
        udm::set_for_test(false);
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
        udm_srv.stop().await.ok();

        assert!(reserved, "precondition: the address was the session's");
        assert_eq!(status, 204);
        assert!(
            deletes
                .iter()
                .any(|u| u.contains("/registrations/smf-registrations/5")),
            "Nudm_UECM_Deregistration of the serving SMF: {deletes:?}"
        );
        assert!(
            deletes
                .iter()
                .any(|u| u.ends_with("/sdm-subscriptions/sub-853")),
            "Nudm_SDM_Unsubscribe: {deletes:?}"
        );
        assert!(freed, "the address is back in the pool");
    }

    // ---- #853 / #912 review: one owner per release; every path cleans up ----

    /// A loopback UDM that answers every request after `delay`, and records
    /// `(method, uri)` (#912 review M2). Points the UDM leg at itself.
    async fn spawn_slow_udm(
        delay: std::time::Duration,
    ) -> (
        nextgcore_sbi::server::SbiServer,
        std::sync::Arc<std::sync::Mutex<Vec<(String, String)>>>,
    ) {
        let seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let (srv, addr) =
            nextgcore_sbi::test_support::sbi_server_on_free_port(move |req: SbiRequest| {
                let sink = sink.clone();
                async move {
                    tokio::time::sleep(delay).await;
                    sink.lock()
                        .unwrap_or_else(|e| e.into_inner())
                        .push((req.header.method.clone(), req.header.uri.clone()));
                    SbiResponse::with_status(204)
                }
            })
            .await;
        std::env::set_var("UDM_SBI_ADDR", "127.0.0.1");
        std::env::set_var("UDM_SBI_PORT", addr.port().to_string());
        udm::set_for_test(true);
        (srv, seen)
    }

    fn stop_udm_leg() {
        udm::set_for_test(false);
        std::env::remove_var("UDM_SBI_ADDR");
        std::env::remove_var("UDM_SBI_PORT");
    }

    /// An ESTABLISHED SM context: a registered session holding `ue_ip` as
    /// `sess.ipv4_addr`, and a binding naming the same address, as a create leaves
    /// them. Returns the reference.
    fn seed_established_session(supi: &str, psi: u8, ue_ip: std::net::Ipv4Addr) -> String {
        let ctx = smf_self();
        let context = ctx.read().expect("context");
        assert!(
            context.ipv4_pool.reserve(ue_ip),
            "precondition: {ue_ip} free"
        );
        let (reference, sess_id) = register_sm_context(&context, supi, psi).expect("register");
        let mut sess = context.sess_find_by_id(sess_id).expect("session");
        sess.ipv4_addr = Some(ue_ip);
        context.sess_update(&sess);
        let mut b = context::PolicyBinding::snapshot_default();
        b.supi = supi.to_string();
        b.psi = psi;
        b.ue_ip = ue_ip.octets();
        b.sdm_subscription_id = Some(format!("sub-{psi}"));
        context
            .policy_bindings
            .write()
            .unwrap()
            .insert(reference.clone(), b);
        context
            .pfcp_sessions
            .write()
            .unwrap()
            .insert(reference.clone(), 0x0912);
        reference
    }

    /// The stage of the one release of (SUPI, PSI) in flight; `Done` once none is.
    fn release_stage(supi: &str, psi: u8) -> UdmReleaseStage {
        releases_in_flight()
            .lock()
            .unwrap()
            .get(&(supi.to_string(), psi))
            .and_then(|l| l.first().map(ReleaseEntry::stage))
            .unwrap_or(UdmReleaseStage::Done)
    }

    /// Poll, at most 5 s, until the release of (SUPI, PSI) reaches `stage`.
    async fn wait_for_stage(supi: &str, psi: u8, stage: UdmReleaseStage) {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);
        while release_stage(supi, psi) != stage {
            assert!(
                std::time::Instant::now() < deadline,
                "{supi}/{psi} never reached {stage:?}"
            );
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        }
    }

    /// Wait until no release side effects run (all spawned tasks done).
    async fn side_effects_settled() {
        drain_release_side_effects(std::time::Duration::from_secs(5)).await;
    }

    /// #912 review B1: an established session's address is freed ONCE. After the
    /// release, "UE B" is given the address; it must still be B's when every release
    /// step has run. Before, the session's removal freed it and the binding freed it
    /// again, so B's allocation was released under it.
    #[tokio::test]
    async fn an_established_sessions_address_is_freed_once() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let ip = std::net::Ipv4Addr::new(10, 45, 9, 12);
        let reference = seed_established_session("imsi-001010000009121", 5, ip);

        let _ = release_sm_context_locally(&reference);
        let pool = |f: &dyn Fn(&context::SmfContext) -> bool| f(&smf_self().read().unwrap());
        let free_after_release = pool(&|c| c.ipv4_pool.reserve(ip)); // UE B takes it
        side_effects_settled().await;
        let still_bs = !pool(&|c| c.ipv4_pool.reserve(ip));
        let map_entry_gone = smf_self()
            .read()
            .unwrap()
            .pfcp_sessions
            .read()
            .unwrap()
            .get(&reference)
            .is_none();
        smf_self().read().unwrap().ipv4_pool.release(ip);

        assert!(free_after_release, "the release freed the address");
        assert!(still_bs, "and only once: B still holds it");
        assert!(map_entry_gone, "the PFCP session map entry is gone");
    }

    /// #912 review B1, deterministically: the session owns the address. A binding
    /// whose `ue_ip` names ANOTHER address (here UE B's) must not free it. Before,
    /// both were freed, which is the double free that, interleaved with a create,
    /// handed one address to two UEs.
    #[tokio::test]
    async fn a_release_frees_only_the_sessions_address() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let a_ip = std::net::Ipv4Addr::new(10, 45, 9, 17);
        let b_ip = std::net::Ipv4Addr::new(10, 45, 9, 18);
        let reference = seed_established_session("imsi-001010000009126", 11, a_ip);
        assert!(
            smf_self().read().unwrap().ipv4_pool.reserve(b_ip),
            "UE B holds b_ip"
        );
        if let Ok(ctx) = smf_self().read() {
            ctx.policy_bindings
                .write()
                .unwrap()
                .get_mut(&reference)
                .unwrap()
                .ue_ip = b_ip.octets();
        }
        let _ = release_sm_context_locally(&reference);
        side_effects_settled().await;
        let ctx = smf_self();
        let ctx = ctx.read().unwrap();
        let a_free = ctx.ipv4_pool.reserve(a_ip);
        let b_still_held = !ctx.ipv4_pool.reserve(b_ip);
        ctx.ipv4_pool.release(a_ip);
        ctx.ipv4_pool.release(b_ip);
        assert!(a_free, "the session's address is freed");
        assert!(b_still_held, "and nothing else");
    }

    /// #912 review M3: a UPF answering cause 65 ("session not found") releases the
    /// context completely: binding, session and address. Before, only the PFCP map
    /// entry went, and the half-live context answered every later request.
    #[tokio::test]
    async fn a_session_the_upf_does_not_know_is_released_completely() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let ip = std::net::Ipv4Addr::new(10, 45, 9, 19);
        let reference = seed_established_session("imsi-001010000009127", 12, ip);
        if let Ok(ctx) = smf_self().read() {
            ctx.pfcp_sessions
                .write()
                .unwrap()
                .insert(reference.clone(), 0x0912_0065);
        }
        assert!(restoration::reconcile_session_not_found(0x0912_0065).await);
        side_effects_settled().await;
        let gone = lookup_policy_binding(&reference).is_none();
        let freed = smf_self().read().unwrap().ipv4_pool.reserve(ip);
        smf_self().read().unwrap().ipv4_pool.release(ip);
        assert!(gone, "the binding is released");
        assert!(freed, "and the address");
    }

    /// #854: a UPF restart releases a session whose binding names no UE completely,
    /// rather than only notifying RELEASED and keeping the binding for good.
    #[tokio::test]
    async fn an_identity_less_session_is_released_completely_on_a_upf_restart() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _n4 = pfcp_path::N4_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let ip = std::net::Ipv4Addr::new(10, 45, 9, 20);
        let reference = seed_established_session("imsi-001010000009128", 13, ip);
        if let Ok(ctx) = smf_self().read() {
            let mut bindings = ctx.policy_bindings.write().unwrap();
            let b = bindings.get_mut(&reference).unwrap();
            b.supi.clear(); // no UE to release it through
            b.sm_context_status_uri = Some("http://127.0.0.1:1/sm-status".to_string());
        }
        let notified = restoration::notify_sessions_unrecoverable("peer restarted").await;
        side_effects_settled().await;
        let gone = lookup_policy_binding(&reference).is_none();
        let freed = smf_self().read().unwrap().ipv4_pool.reserve(ip);
        smf_self().read().unwrap().ipv4_pool.release(ip);
        if let Ok(ctx) = smf_self().read() {
            ctx.pfcp_sessions.write().unwrap().remove(&reference);
        }
        assert!(notified >= 1);
        assert!(gone, "the binding is released");
        assert!(freed, "and the address");
    }

    /// #912 review M1: an AMF /release (slow UDM) racing a T3592 abandon for the same
    /// context. Whichever takes the context frees the address, once; the other finds
    /// nothing. Before, the abandon freed it during the AMF path's UDM await, it went
    /// to UE B, and the AMF path then freed B's address.
    #[tokio::test]
    async fn an_amf_release_racing_t3592_frees_the_address_once() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, _seen) = spawn_slow_udm(std::time::Duration::from_millis(800)).await;
        let ip = std::net::Ipv4Addr::new(10, 45, 9, 13);
        let reference = seed_established_session("imsi-001010000009122", 6, ip);

        let r = reference.clone();
        let amf = tokio::spawn(async move {
            handle_sm_context_release(
                &r,
                Some(&SbiRequest::post(format!(
                    "/nsmf-pdusession/v1/sm-contexts/{r}/release"
                ))),
            )
            .await
            .status
        });
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        abandon_gsm_procedure(&reference, timer::SmfTimerId::T3592).await;
        let given_to_b = smf_self().read().unwrap().ipv4_pool.reserve(ip);
        let status = amf.await.unwrap();
        side_effects_settled().await;
        let still_bs = !smf_self().read().unwrap().ipv4_pool.reserve(ip);
        smf_self().read().unwrap().ipv4_pool.release(ip);
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert_eq!(status, 204);
        assert!(given_to_b, "the AMF path freed it at its take");
        assert!(still_bs, "and nobody freed it again under B");
    }

    /// #912 review M2: a new session for the same (SUPI, PSI) waits for the previous
    /// release's effects at the UDM. A #39 reactivation re-establishes at once; its
    /// UECM registration must not be overtaken by the old release's deregistration.
    #[tokio::test]
    async fn a_new_session_waits_for_the_previous_release_of_its_psi() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, seen) = spawn_slow_udm(std::time::Duration::from_millis(400)).await;
        let supi = "imsi-001010000009123";
        let deletes = |psi: u8| {
            seen.lock()
                .unwrap()
                .iter()
                .filter(|(m, u)| m == "DELETE" && u.ends_with(&format!("/smf-registrations/{psi}")))
                .count()
        };

        // (a) The old deregistration is already on the wire: the create waits for it.
        let on_wire = seed_established_session(supi, 7, std::net::Ipv4Addr::new(10, 45, 9, 14));
        let _ = release_sm_context_locally(&on_wire);
        // The SDM unsubscribe goes first (400 ms); then the DELETE is on the wire.
        wait_for_stage(supi, 7, UdmReleaseStage::Deleting).await;
        let started = std::time::Instant::now();
        await_release_in_flight(supi, 7).await;
        let waited = started.elapsed();
        let landed_before = deletes(7);

        // (b) The old cleanup has not started: the create supersedes it, and the old
        // deregistration is never sent (it would delete the new registration).
        let pending = seed_established_session(supi, 8, std::net::Ipv4Addr::new(10, 45, 9, 21));
        let _ = release_sm_context_locally(&pending);
        let started = std::time::Instant::now();
        await_release_in_flight(supi, 8).await;
        let superseded_in = started.elapsed();
        side_effects_settled().await;
        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
        let late_deletes = deletes(8);
        let unsubscribed = seen
            .lock()
            .unwrap()
            .iter()
            .filter(|(m, u)| m == "DELETE" && u.ends_with("/sdm-subscriptions/sub-8"))
            .count();

        // (c) Another PSI does not wait.
        let other = std::time::Instant::now();
        await_release_in_flight(supi, 9).await;
        let other_waited = other.elapsed();
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert_eq!(
            landed_before, 1,
            "the old deregistration landed before the create returns"
        );
        assert!(
            waited >= std::time::Duration::from_millis(300),
            "{waited:?}"
        );
        assert!(
            superseded_in < std::time::Duration::from_millis(50),
            "{superseded_in:?}"
        );
        assert_eq!(
            late_deletes, 0,
            "a superseded release sends no deregistration"
        );
        assert_eq!(
            unsubscribed, 1,
            "a superseded release still removes its own SDM subscription (#912 review N5)"
        );
        assert!(other_waited < std::time::Duration::from_millis(50));
    }

    /// #912 review N2: SM Context Create itself waits for the previous release of its
    /// (SUPI, PSI). The old Nudm_UECM_Deregistration is on the wire (the UDM answers
    /// DELETEs after 500 ms); a create for the same PSI registers only after it has
    /// been answered, so the old DELETE cannot remove the new registration.
    #[tokio::test]
    async fn a_create_registers_only_after_the_old_deregistration_is_answered() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        let _upf = pfcp_path::stand_in::associated_upf().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        type Seen = std::sync::Arc<
            std::sync::Mutex<Vec<(String, String, std::time::Instant, std::time::Instant)>>,
        >;
        let seen: Seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
        let sink = seen.clone();
        let (udm_srv, addr) =
            nextgcore_sbi::test_support::sbi_server_on_free_port(move |req: SbiRequest| {
                let sink = sink.clone();
                async move {
                    let arrived = std::time::Instant::now();
                    if req.header.method == "DELETE" {
                        tokio::time::sleep(std::time::Duration::from_millis(500)).await;
                    }
                    sink.lock().unwrap().push((
                        req.header.method.clone(),
                        req.header.uri.clone(),
                        arrived,
                        std::time::Instant::now(),
                    ));
                    if req.header.method == "DELETE" {
                        return SbiResponse::with_status(204);
                    }
                    if req.header.uri.contains("/sdm-subscriptions") {
                        return SbiResponse::with_status(201)
                            .with_json_body(&serde_json::json!({ "subscriptionId": "sub-n2" }))
                            .unwrap_or_else(|_| SbiResponse::with_status(201));
                    }
                    if req.header.uri.contains("/sm-data") {
                        return SbiResponse::with_status(200)
                            .with_json_body(&serde_json::json!([]))
                            .unwrap_or_else(|_| SbiResponse::with_status(200));
                    }
                    SbiResponse::with_status(201)
                }
            })
            .await;
        std::env::set_var("UDM_SBI_ADDR", "127.0.0.1");
        std::env::set_var("UDM_SBI_PORT", addr.port().to_string());
        udm::set_for_test(true);
        let supi = "imsi-001010000009129";
        let old = seed_established_session(supi, 6, std::net::Ipv4Addr::new(10, 45, 9, 22));
        let _ = release_sm_context_locally(&old);
        // Past the old SDM unsubscribe: its UECM DELETE is on the wire.
        wait_for_stage(supi, 6, UdmReleaseStage::Deleting).await;

        let resp = handle_sm_context_create(&create_request(
            supi,
            6,
            &n1(
                6,
                1,
                gsm_build::message_type::PDU_SESSION_ESTABLISHMENT_REQUEST,
                &[0x91, 0x00],
            ),
        ))
        .await;
        side_effects_settled().await;
        let log = seen.lock().unwrap().clone();
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert_eq!(resp.status, 201);
        let old_delete_done = log
            .iter()
            .find(|(m, u, _, _)| m == "DELETE" && u.ends_with("/smf-registrations/6"))
            .map(|(_, _, _, done)| *done)
            .expect("the old deregistration was sent");
        let new_put = log
            .iter()
            .find(|(m, u, _, _)| m == "PUT" && u.ends_with("/smf-registrations/6"))
            .map(|(_, _, arrived, _)| *arrived)
            .expect("the new session registered");
        assert!(
            new_put >= old_delete_done,
            "the new registration arrived only after the old deregistration was answered"
        );
    }

    /// #912 review m5/n6: the shutdown drain of release side effects is bounded, and
    /// waits for them when there is time.
    #[tokio::test]
    async fn the_release_side_effect_drain_is_bounded() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, seen) = spawn_slow_udm(std::time::Duration::from_millis(800)).await;
        let reference = seed_established_session(
            "imsi-001010000009131",
            14,
            std::net::Ipv4Addr::new(10, 45, 9, 32),
        );
        let _ = release_sm_context_locally(&reference);
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;

        let started = std::time::Instant::now();
        drain_release_side_effects(std::time::Duration::from_millis(200)).await;
        let short = started.elapsed();
        let unfinished = seen.lock().unwrap().is_empty();
        drain_release_side_effects(std::time::Duration::from_secs(5)).await;
        let finished = !seen.lock().unwrap().is_empty();
        smf_self()
            .read()
            .unwrap()
            .ipv4_pool
            .release(std::net::Ipv4Addr::new(10, 45, 9, 32));
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert!(short < std::time::Duration::from_millis(500), "{short:?}");
        assert!(
            unfinished,
            "the short drain gave up while the UDM was still answering"
        );
        assert!(finished, "the long drain waited for it");
    }

    /// #912 review M4: the UE-requested release (PDU SESSION RELEASE REQUEST, then
    /// COMPLETE) and the T3592 abandon each tell the UDM.
    #[tokio::test]
    async fn ue_requested_and_t3592_releases_tell_the_udm() {
        let _state = crate::context::PROCESS_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, seen) = spawn_slow_udm(std::time::Duration::ZERO).await;
        let requested = seed_established_session(
            "imsi-001010000009124",
            9,
            std::net::Ipv4Addr::new(10, 45, 9, 15),
        );
        let abandoned = seed_established_session(
            "imsi-001010000009125",
            10,
            std::net::Ipv4Addr::new(10, 45, 9, 16),
        );

        let req = n1(
            9,
            4,
            gsm_build::message_type::PDU_SESSION_RELEASE_REQUEST,
            &[],
        );
        let _ = handle_n1_sm_message(&requested, &req).await;
        let complete = n1(
            9,
            4,
            gsm_build::message_type::PDU_SESSION_RELEASE_COMPLETE,
            &[],
        );
        let completed = handle_n1_sm_message(&requested, &complete).await.status;
        abandon_gsm_procedure(&abandoned, timer::SmfTimerId::T3592).await;
        side_effects_settled().await;
        let deletes: Vec<String> = seen
            .lock()
            .unwrap()
            .iter()
            .filter(|(m, _)| m == "DELETE")
            .map(|(_, u)| u.clone())
            .collect();
        for ip in [15u8, 16] {
            smf_self()
                .read()
                .unwrap()
                .ipv4_pool
                .release(std::net::Ipv4Addr::new(10, 45, 9, ip));
        }
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert_eq!(completed, 204);
        for (supi, psi) in [("imsi-001010000009124", 9), ("imsi-001010000009125", 10)] {
            assert!(
                deletes
                    .iter()
                    .any(|u| u.contains(supi) && u.ends_with(&format!("/smf-registrations/{psi}"))),
                "UECM deregistration for {supi}/{psi}: {deletes:?}"
            );
            assert!(
                deletes
                    .iter()
                    .any(|u| u.contains(supi)
                        && u.ends_with(&format!("/sdm-subscriptions/sub-{psi}"))),
                "SDM unsubscribe for {supi}/{psi}: {deletes:?}"
            );
        }
    }

    /// #912 review N4: a UECM deregistration the UDM never answers is bounded by
    /// [`UDM_RELEASE_TIMEOUT`]. A create waiting on it returns within that bound,
    /// and the release reaches `Done`, so the next create waits for nothing.
    #[tokio::test]
    async fn a_deregistration_the_udm_never_answers_holds_a_create_only_for_its_bound() {
        let _state = RELEASE_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, _seen) = spawn_slow_udm(std::time::Duration::from_secs(20)).await;
        let supi = "imsi-001010000009131";
        let reference = seed_established_session(supi, 11, std::net::Ipv4Addr::new(10, 45, 9, 31));
        smf_self()
            .read()
            .unwrap()
            .policy_bindings
            .write()
            .unwrap()
            .get_mut(&reference)
            .unwrap()
            .sdm_subscription_id = None;

        let _ = release_sm_context_locally(&reference);
        wait_for_stage(supi, 11, UdmReleaseStage::Deleting).await;
        let started = std::time::Instant::now();
        await_release_in_flight(supi, 11).await;
        let waited = started.elapsed();
        let done_by = std::time::Instant::now() + std::time::Duration::from_secs(1);
        while release_stage(supi, 11) != UdmReleaseStage::Done
            && std::time::Instant::now() < done_by
        {
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        let stage = release_stage(supi, 11);
        side_effects_settled().await;
        smf_self()
            .read()
            .unwrap()
            .ipv4_pool
            .release(std::net::Ipv4Addr::new(10, 45, 9, 31));
        stop_udm_leg();
        let _ = tokio::time::timeout(std::time::Duration::from_secs(1), udm_srv.stop()).await;

        assert!(
            waited <= std::time::Duration::from_secs(4),
            "a create waits at most the 3 s bound on the old DELETE, not the SBI \
             client's 30 s: {waited:?}"
        );
        assert_eq!(
            stage,
            UdmReleaseStage::Done,
            "the unanswered DELETE was given up at the bound"
        );
    }

    /// #912 review N4: the UDM cleanup is not held behind the release fan-out. With
    /// every fan-out permit taken (other releases' slow EASDF and AMF work), a new
    /// release's UECM DELETE still reaches the UDM at once.
    #[tokio::test]
    async fn the_udm_cleanup_is_not_held_behind_the_release_fanout() {
        let _state = RELEASE_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, seen) = spawn_slow_udm(std::time::Duration::ZERO).await;
        let supi = "imsi-001010000009132";
        let reference = seed_established_session(supi, 12, std::net::Ipv4Addr::new(10, 45, 9, 32));
        let held = release_side_effect_permits()
            .clone()
            .acquire_many_owned(RELEASE_SIDE_EFFECTS_FANOUT as u32)
            .await
            .expect("permits");

        let _ = release_sm_context_locally(&reference);
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        let reached = loop {
            let hit = seen.lock().unwrap().iter().any(|(m, u)| {
                m == "DELETE" && u.contains(supi) && u.ends_with("/smf-registrations/12")
            });
            if hit || std::time::Instant::now() >= deadline {
                break hit;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        };
        drop(held);
        side_effects_settled().await;
        smf_self()
            .read()
            .unwrap()
            .ipv4_pool
            .release(std::net::Ipv4Addr::new(10, 45, 9, 32));
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert!(
            reached,
            "the UECM DELETE went out while every fan-out permit was held"
        );
    }

    /// #912 review o2: the UDM leg is bounded by its own pool. A release queued for
    /// a UDM permit sends nothing and stays `Pending`, so a create for its PSI
    /// supersedes it at once instead of waiting behind the queue.
    #[tokio::test]
    async fn a_release_queued_for_the_udm_is_superseded_not_waited_for() {
        let _state = RELEASE_STATE_TEST_LOCK.lock().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, seen) = spawn_slow_udm(std::time::Duration::ZERO).await;
        let supi = "imsi-001010000009137";
        let reference = seed_established_session(supi, 17, std::net::Ipv4Addr::new(10, 45, 9, 37));
        let held = udm_release_permits()
            .clone()
            .acquire_many_owned(UDM_RELEASE_FANOUT as u32)
            .await
            .expect("permits");

        let _ = release_sm_context_locally(&reference);
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        let sent_while_queued = seen.lock().unwrap().iter().any(|(_, u)| u.contains(supi));
        let stage = release_stage(supi, 17);
        let started = std::time::Instant::now();
        await_release_in_flight(supi, 17).await;
        let waited = started.elapsed();
        drop(held);
        side_effects_settled().await;
        let sent: Vec<String> = seen
            .lock()
            .unwrap()
            .iter()
            .filter(|(m, u)| m == "DELETE" && u.contains(supi))
            .map(|(_, u)| u.clone())
            .collect();
        smf_self()
            .read()
            .unwrap()
            .ipv4_pool
            .release(std::net::Ipv4Addr::new(10, 45, 9, 37));
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert!(
            !sent_while_queued,
            "nothing goes to the UDM without a permit"
        );
        assert_eq!(stage, UdmReleaseStage::Pending);
        assert!(waited < std::time::Duration::from_millis(50), "{waited:?}");
        assert_eq!(
            sent.len(),
            1,
            "once a permit is free, only the SDM unsubscribe goes out: {sent:?}"
        );
        assert!(sent[0].ends_with("/sdm-subscriptions/sub-17"), "{sent:?}");
    }

    /// #912 review n2: two releases of one (SUPI, PSI) in flight together are both
    /// visible to a create, and each removes only its own entry.
    #[tokio::test]
    async fn a_second_release_of_a_psi_does_not_hide_the_first() {
        let _state = RELEASE_STATE_TEST_LOCK.lock().await;
        let supi = "imsi-001010000009133";
        let first = ReleaseInFlight::begin(supi, 13);
        let second = ReleaseInFlight::begin(supi, 13);
        assert!(
            first.entry.begin_deregistration(),
            "the first DELETE is on the wire"
        );

        let waiter = tokio::spawn(async move {
            let started = std::time::Instant::now();
            await_release_in_flight(supi, 13).await;
            started.elapsed()
        });
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        let second_superseded = !second.entry.begin_deregistration();
        drop(second);
        let in_map = releases_in_flight()
            .lock()
            .unwrap()
            .get(&(supi.to_string(), 13))
            .map_or(0, Vec::len);
        drop(first);
        let waited = waiter.await.unwrap();
        let after = releases_in_flight()
            .lock()
            .unwrap()
            .contains_key(&(supi.to_string(), 13));

        assert!(
            second_superseded,
            "the pending second release was superseded"
        );
        assert_eq!(in_map, 1, "dropping the second left the first in flight");
        assert!(
            waited >= std::time::Duration::from_millis(150),
            "the create waited for the first release's DELETE: {waited:?}"
        );
        assert!(!after, "the last drop removes the key");
    }

    /// #912 review n3: when the user-plane release finds the UPF holds no such
    /// session (cause 65), the reconciliation completes the whole release, and no
    /// T3592 is armed for the context that is gone: not on the UE-requested path,
    /// not on the RAN-released one.
    #[tokio::test]
    async fn no_t3592_for_a_context_the_user_plane_release_completed() {
        let _state = RELEASE_STATE_TEST_LOCK.lock().await;
        let upf = pfcp_path::stand_in::associated_upf().await;
        nextgcore_sbi::security::set_sbi_profile_override(nextgcore_sbi::security::SbiProfile::Dev);
        smf_context_init(64, 256, 512);
        let (udm_srv, _seen) = spawn_slow_udm(std::time::Duration::ZERO).await;
        upf.answer_sessions_with(pfcp_path::pfcp_cause::SESSION_CONTEXT_NOT_FOUND);
        let ue = seed_established_session(
            "imsi-001010000009134",
            14,
            std::net::Ipv4Addr::new(10, 45, 9, 34),
        );
        let ran = seed_established_session(
            "imsi-001010000009135",
            15,
            std::net::Ipv4Addr::new(10, 45, 9, 35),
        );
        for (r, seid) in [(&ue, 0x0912_0134_u64), (&ran, 0x0912_0135)] {
            smf_self()
                .read()
                .unwrap()
                .pfcp_sessions
                .write()
                .unwrap()
                .insert(r.clone(), seid);
        }

        let req = n1(
            14,
            5,
            gsm_build::message_type::PDU_SESSION_RELEASE_REQUEST,
            &[],
        );
        let ue_status = handle_n1_sm_message(&ue, &req).await.status;
        let ran_status = ran_released_session(&ran, None).await.status;
        let armed: Vec<bool> = [&ue, &ran]
            .iter()
            .map(|r| {
                gsm_procedure_timers()
                    .lock()
                    .unwrap()
                    .contains_key(r.as_str())
            })
            .collect();
        let gone: Vec<bool> = [&ue, &ran]
            .iter()
            .map(|r| lookup_policy_binding(r).is_none())
            .collect();
        side_effects_settled().await;
        for r in [&ue, &ran] {
            gsm_procedure_timers().lock().unwrap().remove(r.as_str());
        }
        stop_udm_leg();
        udm_srv.stop().await.ok();

        assert_eq!((ue_status, ran_status), (200, 200));
        assert_eq!(gone, [true, true], "cause 65 completed both releases");
        assert_eq!(armed, [false, false], "no T3592 for a context that is gone");
    }

    /// #912 review n4: a failed create's rollback removes the binding it inserted,
    /// the session, and frees the address once, whether or not the session already
    /// held it.
    #[tokio::test]
    async fn a_create_rollback_removes_its_binding_and_frees_the_address() {
        let _state = RELEASE_STATE_TEST_LOCK.lock().await;
        smf_context_init(64, 256, 512);
        let held = std::net::Ipv4Addr::new(10, 45, 9, 36);
        let reference = seed_established_session("imsi-001010000009136", 16, held);
        let sess_id = smf_self()
            .read()
            .unwrap()
            .sess_find_by_sm_context_ref(&reference)
            .unwrap()
            .id;
        let before = smf_self().read().unwrap().ipv4_pool.allocated_addrs().len();
        let stale = smf_self().read().unwrap().ipv4_pool.stale_releases();

        rollback_sm_context_create(&reference, Some(sess_id), held.octets());
        // #912 review r2: a second free of the same address is counted, so the
        // double free this test is named for is visible within one call.
        let double_freed = smf_self().read().unwrap().ipv4_pool.stale_releases() - stale;

        let ctx = smf_self();
        let ctx = ctx.read().unwrap();
        let binding_left = ctx.policy_bindings.read().unwrap().contains_key(&reference);
        let sess_left = ctx.sess_find_by_id(sess_id).is_some();
        let after = ctx.ipv4_pool.allocated_addrs().len();
        let free_again = ctx.ipv4_pool.reserve(held);
        ctx.ipv4_pool.release(held);
        drop(ctx);
        let _ = take_sm_context(&reference);

        assert!(!binding_left, "the inserted binding is removed");
        assert!(!sess_left, "the session is removed");
        assert_eq!(after + 1, before, "the address is freed once");
        assert_eq!(double_freed, 0, "and not freed a second time");
        assert!(free_again);
    }

    /// #1075 (#1072 round 2 m3): a released session's DECREASE names the nfId its
    /// INCREASE carried, not this instance's current one (TS 23.502 §4.2.11.2: the
    /// NSACF tells one UE's entries apart by it).
