        let status = handle_sm_context_create(&create_request(
            supi,
            14,
            &n1(
                14,
                1,
                gsm_build::message_type::PDU_SESSION_ESTABLISHMENT_REQUEST,
                &[0x91, 0x00],
            ),
        ))
        .await
        .status;
